begin;
insert into public.posts(environment,legacy_id,title,slug,summary,content,legacy_article_html,original_schema,thumbnail,thumbnail_alt,category_id,status,created_by,created_at,published_at)
select 'preview',p.legacy_id,p.title,p.slug,p.summary,p.content,p.legacy_article_html,p.original_schema,p.thumbnail,p.thumbnail_alt,p.category_id,'published',
 (select user_id from public.admin_users where username='yammo0516'),p.created_at,p.published_at
from jsonb_to_recordset('[{"legacy_id":"1","title":"임플란트 교체 시기와 수명, 언제 다시 치료해야 할까요?","slug":"임플란트-교체-시기와-수명","summary":"임플란트는 몇 년마다 교체해야 할까요? 사용 기간만으로 판단하기보다 몸체와 보철물, 주변 잇몸과 뼈의 상태를 함께 살펴야 합니다. 교체를 고려하는 변화와 오래 사용하기 위한 일상 관리, 정기검진 때 확인할 내용을 정리했습니다.","content":[{"type":"image","src":"/images/lifespan.png","alt":"임플란트 수명과 상태 평가를 표현한 설명용 이미지","caption":""},{"type":"text","text":"임플란트 몸체와 보철물은 다릅니다\n우리가 흔히 ‘임플란트’라고 부르는 것은 하나의 부품만을 뜻하지 않습니다. 턱뼈에 들어가는 임플란트 몸체, 몸체와 인공 치아를 연결하는 지대주, 씹는 기능을 하는 보철물로 이루어집니다."},{"type":"text","text":"따라서 ‘임플란트를 교체한다’는 말도 구분해서 이해할 필요가 있습니다. 위쪽 보철물이나 연결 부품을 수리하는 것과 턱뼈 속 몸체를 제거하고 다시 식립하는 것은 서로 다른 치료입니다."},{"type":"text","text":"몇 년마다 반드시 바꿔야 할까요?\n모든 사람에게 적용되는 고정된 교체 연수를 정하기는 어렵습니다. 임플란트는 적절하게 관리하면 오래 사용할 수 있지만, 개인의 건강 상태와 유지관리, 주변 조직의 상태에 따라 경과가 달라집니다."},{"type":"text","text":"‘10년이 지나면 반드시 교체’ 또는 ‘평생 문제가 없다’는 표현으로 자신의 상태를 판단하지 마세요. 오래 사용했다는 이유만으로 교체를 결정하기보다 현재 기능과 주변 조직을 치과에서 평가하는 것이 중요합니다."},{"type":"text","text":"보철물의 문제와 몸체의 문제를 구분해요\n임플란트 연결 나사가 느슨해지면 치아가 움직이거나 돌아가는 듯한 느낌이 생길 수 있습니다. 부품이 마모되거나 느슨해지는 문제도 발생할 수 있습니다. 반면 임플란트 몸체 자체가 안정성을 잃는 것은 별도로 평가해야 할 문제입니다."},{"type":"text","text":"불편하다고 해서 곧바로 임플란트 전체를 교체하는 것은 아닙니다. 어떤 부품과 조직에 문제가 있는지 확인한 뒤 수리 또는 교체가 필요한 범위를 상담합니다."},{"type":"text","text":"이런 변화가 있다면 치과에 알려주세요\n임플란트가 흔들리거나 통증이 느껴진다면 치과에 바로 연락하세요. 임플란트 주변 잇몸이 붉어지거나 압통이 생기고, 양치할 때 출혈이 반복되는 것도 확인이 필요한 변화입니다."},{"type":"text","text":"임플란트 주위 질환은 잇몸에 국한된 염증과 주변 뼈까지 영향을 주는 상태로 나뉩니다. 증상만으로 어느 상태인지 스스로 판단하거나 부품을 직접 조절하지 말고 치과에서 평가받으세요."},{"type":"text","text":"수명을 위해 중요한 일상 관리\n임플란트 주변에도 세균성 치태가 쌓일 수 있어 자연치아처럼 위생 관리가 필요합니다. 담당 치과에서 안내한 방법으로 임플란트와 주변 치아를 닦고 치아 사이를 관리하세요."},{"type":"text","text":"흡연은 임플란트의 치유와 장기적인 경과에 영향을 줄 수 있습니다. 치주질환 병력, 치태 관리, 당뇨 등도 주변 조직의 건강을 살필 때 고려하는 요소입니다. 현재 건강 상태와 복용 중인 약을 담당 치과에 알려주세요."},{"type":"text","text":"정기검진은 내 상태에 맞춰 계획해요\n정기적인 치과 방문은 장기 관리의 중요한 부분입니다. 모든 사람에게 같은 검진 간격을 적용하기보다 담당 치과와 다음 방문 시기를 정하고 안내받은 일정을 지키세요."},{"type":"text","text":"상담할 때는 ‘보철물의 문제인가요, 몸체나 주변 조직의 문제인가요?’, ‘수리가 가능한가요?’, ‘다음 점검은 언제 하면 될까요?’를 물어보세요. 사용한 임플란트의 제조사와 모델 정보도 기록해 두면 이후 진료에 도움이 됩니다."},{"type":"text","text":"교체 연수보다 현재 상태를 확인하세요\n임플란트 관리의 핵심은 달력에 적힌 교체 연수가 아니라 안정적인 기능과 주변 조직의 건강입니다. 불편한 변화가 있으면 예정된 검진일까지 기다리지 말고 담당 치과에 문의하세요."},{"type":"text","text":"이 글은 일반적인 정보를 정리한 AI 작성 초안이며 치과 의료진 검수를 받지 않았습니다. 개인의 진단·치료 계획을 대신하지 않습니다."}],"thumbnail":"/images/lifespan.png","thumbnail_alt":"임플란트 수명과 상태 평가를 표현한 설명용 이미지","category_id":"implant","legacy_article_html":"<article><div class=\"crumb\"><a href=\"/index.html\">홈</a> / 치과 건강정보 / 임플란트</div><h1>임플란트 교체 시기와 수명, 언제 다시 치료해야 할까요?</h1><p class=\"intro\">임플란트를 오래 사용하려면 사용 연수와 함께 잇몸·뼈·보철물의 상태를 확인해야 합니다. 임플란트 몸체와 보철물의 차이부터 교체를 판단하는 기준, 정기 관리까지 차근차근 정리합니다.</p><div class=\"metadata\">원더플치과의원 블로그 · AI 작성 초안 · 작성 2026-10-08 · 수정 2026-10-08 · 치과 의료진 검수 전</div><img class=\"hero-image\" src=\"/implant-lifespan-0.svg\" alt=\"임플란트 교체 시기와 수명, 언제 다시 치료해야 할까요? 안내 썸네일\"><p class=\"caption\">구성 안내 이미지 · 실제 환자 또는 의료 사례 이미지가 아닙니다.</p><div class=\"info-box\">한눈에 보기: 임플란트 몸체와 보철물은 구분해서 평가합니다. 정해진 연수만으로 교체를 결정하지 않습니다.</div><div class=\"toc\"><div class=\"eyebrow\">목차 · CONTENTS</div><ol><li><a href=\"#about\">임플란트 몸체와 보철물은 다릅니다</a></li><li><a href=\"#lifespan\">몇 년마다 반드시 바꿔야 할까요?</a></li><li><a href=\"#parts\">보철물의 문제와 몸체의 문제를 구분해요</a></li><li><a href=\"#signs\">이런 변화가 있다면 치과에 알려주세요</a></li><li><a href=\"#care\">수명을 위해 중요한 일상 관리</a></li><li><a href=\"#checkup\">정기검진은 내 상태에 맞춰 계획해요</a></li><li><a href=\"#summary\">교체 연수보다 현재 상태를 확인하세요</a></li></ol></div><section class=\"section\" id=\"about\"><h2><span>01</span>임플란트 몸체와 보철물은 다릅니다</h2><p>우리가 흔히 ‘임플란트’라고 부르는 것은 하나의 부품만을 뜻하지 않습니다. 턱뼈에 들어가는 임플란트 몸체, 몸체와 인공 치아를 연결하는 지대주, 씹는 기능을 하는 보철물로 이루어집니다.\n\n따라서 ‘임플란트를 교체한다’는 말도 구분해서 이해할 필요가 있습니다. 위쪽 보철물이나 연결 부품을 수리하는 것과 턱뼈 속 몸체를 제거하고 다시 식립하는 것은 서로 다른 치료입니다.</p><figure class=\"paragraph-image\"><img src=\"/images/about.png\" alt=\"임플란트 몸체·지대주·보철물을 분리해 보여주는 모형\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure><div class=\"parts\"><div><strong>몸체</strong>턱뼈 안에서 지지</div><div><strong>지대주</strong>몸체와 보철물을 연결</div><div><strong>보철물</strong>씹는 면을 구성</div></div></section><section class=\"section\" id=\"lifespan\"><h2><span>02</span>몇 년마다 반드시 바꿔야 할까요?</h2><p>모든 사람에게 적용되는 고정된 교체 연수를 정하기는 어렵습니다. 임플란트는 적절하게 관리하면 오래 사용할 수 있지만, 개인의 건강 상태와 유지관리, 주변 조직의 상태에 따라 경과가 달라집니다.\n\n‘10년이 지나면 반드시 교체’ 또는 ‘평생 문제가 없다’는 표현으로 자신의 상태를 판단하지 마세요. 오래 사용했다는 이유만으로 교체를 결정하기보다 현재 기능과 주변 조직을 치과에서 평가하는 것이 중요합니다.</p><figure class=\"paragraph-image\"><img src=\"/images/lifespan.png\" alt=\"임플란트 모형과 달력·확대경으로 표현한 상태 점검\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section class=\"section\" id=\"parts\"><h2><span>03</span>보철물의 문제와 몸체의 문제를 구분해요</h2><p>임플란트 연결 나사가 느슨해지면 치아가 움직이거나 돌아가는 듯한 느낌이 생길 수 있습니다. 부품이 마모되거나 느슨해지는 문제도 발생할 수 있습니다. 반면 임플란트 몸체 자체가 안정성을 잃는 것은 별도로 평가해야 할 문제입니다.\n\n불편하다고 해서 곧바로 임플란트 전체를 교체하는 것은 아닙니다. 어떤 부품과 조직에 문제가 있는지 확인한 뒤 수리 또는 교체가 필요한 범위를 상담합니다.</p><figure class=\"paragraph-image\"><img src=\"/images/parts.png\" alt=\"보철물과 연결 부품을 나누어 살펴보는 모형\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section class=\"section\" id=\"signs\"><h2><span>04</span>이런 변화가 있다면 치과에 알려주세요</h2><p>임플란트가 흔들리거나 통증이 느껴진다면 치과에 바로 연락하세요. 임플란트 주변 잇몸이 붉어지거나 압통이 생기고, 양치할 때 출혈이 반복되는 것도 확인이 필요한 변화입니다.\n\n임플란트 주위 질환은 잇몸에 국한된 염증과 주변 뼈까지 영향을 주는 상태로 나뉩니다. 증상만으로 어느 상태인지 스스로 판단하거나 부품을 직접 조절하지 말고 치과에서 평가받으세요.</p><figure class=\"paragraph-image\"><img src=\"/images/signs.png\" alt=\"불편한 증상을 치과 의료진과 상담하는 장면\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section class=\"section\" id=\"care\"><h2><span>05</span>수명을 위해 중요한 일상 관리</h2><p>임플란트 주변에도 세균성 치태가 쌓일 수 있어 자연치아처럼 위생 관리가 필요합니다. 담당 치과에서 안내한 방법으로 임플란트와 주변 치아를 닦고 치아 사이를 관리하세요.\n\n흡연은 임플란트의 치유와 장기적인 경과에 영향을 줄 수 있습니다. 치주질환 병력, 치태 관리, 당뇨 등도 주변 조직의 건강을 살필 때 고려하는 요소입니다. 현재 건강 상태와 복용 중인 약을 담당 치과에 알려주세요.</p><figure class=\"paragraph-image\"><img src=\"/images/care.png\" alt=\"칫솔과 치간 관리 도구를 이용한 일상 관리\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section class=\"section\" id=\"checkup\"><h2><span>06</span>정기검진은 내 상태에 맞춰 계획해요</h2><p>정기적인 치과 방문은 장기 관리의 중요한 부분입니다. 모든 사람에게 같은 검진 간격을 적용하기보다 담당 치과와 다음 방문 시기를 정하고 안내받은 일정을 지키세요.\n\n상담할 때는 ‘보철물의 문제인가요, 몸체나 주변 조직의 문제인가요?’, ‘수리가 가능한가요?’, ‘다음 점검은 언제 하면 될까요?’를 물어보세요. 사용한 임플란트의 제조사와 모델 정보도 기록해 두면 이후 진료에 도움이 됩니다.</p><figure class=\"paragraph-image\"><img src=\"/images/checkup.png\" alt=\"치과 의료진과 정기 점검 계획을 상담하는 장면\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section class=\"section\" id=\"summary\"><h2><span>07</span>교체 연수보다 현재 상태를 확인하세요</h2><p>임플란트 관리의 핵심은 달력에 적힌 교체 연수가 아니라 안정적인 기능과 주변 조직의 건강입니다. 불편한 변화가 있으면 예정된 검진일까지 기다리지 말고 담당 치과에 문의하세요.\n\n이 글은 일반적인 정보를 정리한 AI 작성 초안이며 치과 의료진 검수를 받지 않았습니다. 개인의 진단·치료 계획을 대신하지 않습니다.</p><figure class=\"paragraph-image\"><img src=\"/images/summary.png\" alt=\"위생 관리와 정기 점검을 함께 표현한 그림\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section class=\"section sources\" id=\"sources\"><h2>참고 출처</h2><ol><li id=\"source-1\"><a href=\"https://www.guysandstthomas.nhs.uk/health-information/dental-implants\" target=\"_blank\" rel=\"noopener noreferrer\">Guy’s and St Thomas’ NHS — Dental implants ↗</a></li><li id=\"source-2\"><a href=\"https://www.fda.gov/medical-devices/dental-devices/dental-implants-what-you-should-know\" target=\"_blank\" rel=\"noopener noreferrer\">미국 FDA — Dental Implants: What You Should Know ↗</a></li><li id=\"source-3\"><a href=\"https://www.perio.org/for-patients/periodontal-treatments-and-procedures/dental-implant-procedures/peri-implant-diseases/\" target=\"_blank\" rel=\"noopener noreferrer\">미국치주학회(AAP) — Peri-Implant Diseases ↗</a></li></ol><p>자료 확인일: 2026-10-08. 참고 사이트는 화면 구성만 참고했으며, 의료 내용은 위 자료를 바탕으로 새로 작성했습니다.</p></section><section id=\"contact\"><h2>홈페이지 · 상담 · 예약</h2><div class=\"contact-grid\"><a class=\"contact-link\" href=\"https://wonderplant1.kr/\"><b>W</b><div><small>CONTACT</small>홈페이지 방문 · 원더플치과의원</div></a><a class=\"contact-link\" href=\"tel:029862275\"><b>☎</b><div><small>CONTACT</small>전화 예약 · 원더플치과의원</div></a><a class=\"contact-link\" href=\"https://booking.naver.com/booking/13/bizes/270552\"><b>N</b><div><small>CONTACT</small>온라인 예약 · 원더플치과의원</div></a><a class=\"contact-link\" href=\"https://pf.kakao.com/_ZxmjxcT\"><b>T</b><div><small>CONTACT</small>상담 채널 · 원더플치과의원</div></a></div><p class=\"caption\">치과 연결 정보가 등록되면 버튼이 활성화됩니다.</p></section><section class=\"related-post\"><h2>함께 읽는 글</h2><a href=\"/implant-gum-bleeding.html\">임플란트 잇몸 출혈, 피가 나면 교체해야 하나요? →</a></section><div class=\"tags\" aria-label=\"관련 키워드\"><span class=\"tag\">#임플란트수명</span><span class=\"tag\">#임플란트교체시기</span><span class=\"tag\">#임플란트보철물</span><span class=\"tag\">#임플란트주위염</span><span class=\"tag\">#임플란트관리</span><span class=\"tag\">#치과정기검진</span></div><div class=\"notice\">이 글은 일반적인 건강 정보를 정리한 AI 작성 초안이며 의료진 검수 전입니다. 개인의 진단·치료를 대신하지 않습니다. 치료 방법과 결과는 개인 상태에 따라 다릅니다.</div></article>","original_schema":{"@context":"https://schema.org","@type":"BlogPosting","headline":"임플란트 교체 시기와 수명, 언제 다시 치료해야 할까요?","description":"임플란트를 오래 사용하려면 사용 연수와 함께 잇몸·뼈·보철물의 상태를 확인해야 합니다. 임플란트 몸체와 보철물의 차이부터 교체를 판단하는 기준, 정기 관리까지 차근차근 정리합니다.","datePublished":"2026-10-08","dateCreated":"2026-10-08","dateModified":"2026-10-08","author":{"@type":"Organization","name":"원더플치과의원 블로그 · AI 작성 초안"},"keywords":["임플란트수명","임플란트교체시기","임플란트보철물","임플란트주위염","임플란트관리","치과정기검진"],"url":"https://beautiful-semolina-aa2c94.netlify.app/implant-lifespan.html","mainEntityOfPage":"https://beautiful-semolina-aa2c94.netlify.app/implant-lifespan.html","articleBody":"임플란트 몸체와 보철물은 다릅니다\n우리가 흔히 ‘임플란트’라고 부르는 것은 하나의 부품만을 뜻하지 않습니다. 턱뼈에 들어가는 임플란트 몸체, 몸체와 인공 치아를 연결하는 지대주, 씹는 기능을 하는 보철물로 이루어집니다.\n\n따라서 ‘임플란트를 교체한다’는 말도 구분해서 이해할 필요가 있습니다. 위쪽 보철물이나 연결 부품을 수리하는 것과 턱뼈 속 몸체를 제거하고 다시 식립하는 것은 서로 다른 치료입니다.\n\n몇 년마다 반드시 바꿔야 할까요?\n모든 사람에게 적용되는 고정된 교체 연수를 정하기는 어렵습니다. 임플란트는 적절하게 관리하면 오래 사용할 수 있지만, 개인의 건강 상태와 유지관리, 주변 조직의 상태에 따라 경과가 달라집니다.\n\n‘10년이 지나면 반드시 교체’ 또는 ‘평생 문제가 없다’는 표현으로 자신의 상태를 판단하지 마세요. 오래 사용했다는 이유만으로 교체를 결정하기보다 현재 기능과 주변 조직을 치과에서 평가하는 것이 중요합니다.\n\n보철물의 문제와 몸체의 문제를 구분해요\n임플란트 연결 나사가 느슨해지면 치아가 움직이거나 돌아가는 듯한 느낌이 생길 수 있습니다. 부품이 마모되거나 느슨해지는 문제도 발생할 수 있습니다. 반면 임플란트 몸체 자체가 안정성을 잃는 것은 별도로 평가해야 할 문제입니다.\n\n불편하다고 해서 곧바로 임플란트 전체를 교체하는 것은 아닙니다. 어떤 부품과 조직에 문제가 있는지 확인한 뒤 수리 또는 교체가 필요한 범위를 상담합니다.\n\n이런 변화가 있다면 치과에 알려주세요\n임플란트가 흔들리거나 통증이 느껴진다면 치과에 바로 연락하세요. 임플란트 주변 잇몸이 붉어지거나 압통이 생기고, 양치할 때 출혈이 반복되는 것도 확인이 필요한 변화입니다.\n\n임플란트 주위 질환은 잇몸에 국한된 염증과 주변 뼈까지 영향을 주는 상태로 나뉩니다. 증상만으로 어느 상태인지 스스로 판단하거나 부품을 직접 조절하지 말고 치과에서 평가받으세요.\n\n수명을 위해 중요한 일상 관리\n임플란트 주변에도 세균성 치태가 쌓일 수 있어 자연치아처럼 위생 관리가 필요합니다. 담당 치과에서 안내한 방법으로 임플란트와 주변 치아를 닦고 치아 사이를 관리하세요.\n\n흡연은 임플란트의 치유와 장기적인 경과에 영향을 줄 수 있습니다. 치주질환 병력, 치태 관리, 당뇨 등도 주변 조직의 건강을 살필 때 고려하는 요소입니다. 현재 건강 상태와 복용 중인 약을 담당 치과에 알려주세요.\n\n정기검진은 내 상태에 맞춰 계획해요\n정기적인 치과 방문은 장기 관리의 중요한 부분입니다. 모든 사람에게 같은 검진 간격을 적용하기보다 담당 치과와 다음 방문 시기를 정하고 안내받은 일정을 지키세요.\n\n상담할 때는 ‘보철물의 문제인가요, 몸체나 주변 조직의 문제인가요?’, ‘수리가 가능한가요?’, ‘다음 점검은 언제 하면 될까요?’를 물어보세요. 사용한 임플란트의 제조사와 모델 정보도 기록해 두면 이후 진료에 도움이 됩니다.\n\n교체 연수보다 현재 상태를 확인하세요\n임플란트 관리의 핵심은 달력에 적힌 교체 연수가 아니라 안정적인 기능과 주변 조직의 건강입니다. 불편한 변화가 있으면 예정된 검진일까지 기다리지 말고 담당 치과에 문의하세요.\n\n이 글은 일반적인 정보를 정리한 AI 작성 초안이며 치과 의료진 검수를 받지 않았습니다. 개인의 진단·치료 계획을 대신하지 않습니다.","citation":["https://www.guysandstthomas.nhs.uk/health-information/dental-implants","https://www.fda.gov/medical-devices/dental-devices/dental-implants-what-you-should-know","https://www.perio.org/for-patients/periodontal-treatments-and-procedures/dental-implant-procedures/peri-implant-diseases/"]},"published_at":"2026-10-08","created_at":"2026-10-08"},{"legacy_id":"2","title":"임플란트 잇몸 출혈, 피가 나면 교체해야 하나요?","slug":"임플란트-잇몸-출혈","summary":"임플란트 주변 잇몸에서 피가 나면 바로 교체해야 할까요? 출혈이 나타나는 이유와 잇몸 염증의 차이, 치과에 알려야 할 변화를 살펴봅니다. 평소 위생 관리와 정기 점검을 통해 현재 상태를 확인하는 데 필요한 내용을 정리했습니다.","content":[{"type":"image","src":"/images/bleeding.png","alt":"임플란트 주변 잇몸 상태를 확인하는 설명용 이미지","caption":""},{"type":"text","text":"출혈이 곧 임플란트 교체를 뜻하지는 않습니다\n양치할 때 임플란트 주변에서 피가 나면 임플란트가 망가진 것은 아닌지 걱정될 수 있습니다. 하지만 출혈만으로 임플란트 몸체를 제거하거나 다시 심어야 한다고 판단할 수는 없습니다."},{"type":"text","text":"치과에서는 주변 조직에 어떤 문제가 있는지 확인합니다. 잇몸에 국한된 염증과 지지하는 뼈까지 영향을 받은 상태는 구분해야 하며, 임플란트가 흔들리는지도 평가합니다."},{"type":"text","text":"피가 나는 이유: 임플란트 주변의 염증\n임플란트 주변에도 세균성 치태가 쌓일 수 있습니다. 치태가 주변 잇몸을 자극하면 붉어짐, 부기, 양치할 때의 출혈 같은 변화가 나타날 수 있습니다."},{"type":"text","text":"반복되는 출혈을 단순히 양치 때문이라고 넘기기보다 치과에서 원인을 확인하세요. 과거 치주질환, 치태 관리 상태, 흡연 등은 임플란트 주변 조직의 건강을 살필 때 함께 고려하는 요소입니다."},{"type":"text","text":"점막염과 주위염, 무엇이 다른가요?\n임플란트 주위 점막염은 주변의 연조직에 염증이 있으면서 지지하는 뼈의 소실은 없는 상태를 말합니다. 일찍 발견하면 위생 관리와 전문적인 치료로 호전될 가능성이 있습니다."},{"type":"text","text":"임플란트 주위염은 주변 조직의 염증과 함께 임플란트를 지지하는 뼈에 손상이 있는 상태입니다. 출혈이 얼마나 많이 보이는지만으로 두 상태를 구분할 수 없으므로 치과 평가가 필요합니다."},{"type":"text","text":"관리 방법: 치과 안내에 맞춘 위생 관리\n임플란트와 주변 치아를 꾸준히 청결하게 관리하는 것은 중요합니다. 담당 치과에서 안내한 방법으로 양치하고 치아 사이를 관리하세요. 반복되는 출혈이 있다면 도구와 사용 방법이 적절한지도 상담할 수 있습니다."},{"type":"text","text":"집에서의 관리만으로 모든 염증을 해결할 수 있는 것은 아닙니다. 치과에서 전문적인 세정이나 추가 치료가 필요할 수 있고, 치료 후에도 상태를 다시 확인하는 일정이 중요합니다."},{"type":"text","text":"이런 변화가 있다면 치과에 연락하세요\n양치나 치아 사이 관리 중 출혈이 반복되거나 잇몸이 붓고, 입 냄새나 불쾌한 맛이 새로 나타나면 치과에 문의하세요. 임플란트가 흔들리거나 통증이 있으면 바로 담당 치과에 알려야 합니다."},{"type":"text","text":"다음 정기검진까지 기다리기보다 증상이 언제부터 시작됐는지, 어느 부위에서 생기는지 정리해서 전달하세요. 이런 변화만으로 치료 방법이 정해지는 것은 아니며, 치과에서 원인과 상태를 확인해야 합니다."},{"type":"text","text":"자주 묻는 질문\nQ. 한 번 피가 났는데도 반드시 임플란트를 교체하나요?\nA. 출혈 하나만으로 교체를 결정할 수는 없습니다. 반복 여부와 주변 조직의 상태를 확인해야 합니다."},{"type":"text","text":"Q. 양치만 잘하면 주위염도 해결되나요?\nA. 위생 관리는 중요하지만, 뼈까지 영향을 받은 상태라면 추가 치료가 필요할 수 있습니다. 상태에 맞는 치료 계획을 상담하세요."},{"type":"text","text":"Q. 임플란트가 흔들리면 어떻게 하나요?\nA. 바로 담당 치과에 알리세요. 연결 부품의 느슨함과 몸체의 안정성 문제 등은 구분해서 평가해야 합니다."},{"type":"text","text":"출혈을 무시하지 말고, 상태부터 확인하세요\n임플란트 잇몸 출혈은 곧바로 교체가 필요하다는 뜻은 아니지만 주변 조직을 살펴봐야 하는 신호일 수 있습니다. 반복되는 출혈이나 흔들림, 통증이 있다면 치과에 문의하세요."},{"type":"text","text":"임플란트를 유지할 수 있는지, 어떤 치료가 필요한지는 개별 상태에 따라 다릅니다. 이 글은 일반적인 정보이며 개인의 진단과 치료 계획을 대신하지 않습니다."}],"thumbnail":"/images/bleeding.png","thumbnail_alt":"임플란트 주변 잇몸 상태를 확인하는 설명용 이미지","category_id":"complex-implant","legacy_article_html":"<article><div class=\"crumb\"><a href=\"/index.html\">홈</a> / 치과 건강정보 / 임플란트</div><h1>임플란트 잇몸 출혈, 피가 나면 교체해야 하나요?</h1><p class=\"intro\">임플란트 주변 잇몸에서 피가 난다고 해서 곧바로 임플란트를 교체하는 것은 아닙니다. 출혈은 주변 잇몸의 염증을 알리는 신호일 수 있으며, 교체 여부는 뼈와 임플란트의 안정성 등 실제 상태를 확인한 뒤 판단합니다.</p><div class=\"metadata\">원더플치과의원 블로그 · 작성 2026-10-08 · 수정 2026-10-08</div><img class=\"hero-image\" src=\"/implant-gum-bleeding-0.svg\" alt=\"임플란트 잇몸 출혈, 피가 나면 교체해야 하나요? 안내 썸네일\"><p class=\"caption\">구성 안내 이미지 · 실제 환자 또는 의료 사례 이미지가 아닙니다.</p><div class=\"info-box\">한눈에 보기: 출혈만으로 교체를 결정하지 않습니다. 주변 잇몸의 염증과 뼈 상태를 확인하고, 반복되는 출혈이나 흔들림이 있으면 치과에 연락하세요.</div><div class=\"toc\"><div class=\"eyebrow\">목차 · CONTENTS</div><ol><li><a href=\"#about\">출혈이 곧 임플란트 교체를 뜻하지는 않습니다</a></li><li><a href=\"#lifespan\">피가 나는 이유: 임플란트 주변의 염증</a></li><li><a href=\"#parts\">점막염과 주위염, 무엇이 다른가요?</a></li><li><a href=\"#care\">관리 방법: 치과 안내에 맞춘 위생 관리</a></li><li><a href=\"#signs\">이런 변화가 있다면 치과에 연락하세요</a></li><li><a href=\"#checkup\">자주 묻는 질문</a></li><li><a href=\"#summary\">출혈을 무시하지 말고, 상태부터 확인하세요</a></li></ol></div><section class=\"section\" id=\"about\"><h2><span>01</span>출혈이 곧 임플란트 교체를 뜻하지는 않습니다</h2><p>양치할 때 임플란트 주변에서 피가 나면 임플란트가 망가진 것은 아닌지 걱정될 수 있습니다. 하지만 출혈만으로 임플란트 몸체를 제거하거나 다시 심어야 한다고 판단할 수는 없습니다.\n\n치과에서는 주변 조직에 어떤 문제가 있는지 확인합니다. 잇몸에 국한된 염증과 지지하는 뼈까지 영향을 받은 상태는 구분해야 하며, 임플란트가 흔들리는지도 평가합니다.</p><figure class=\"paragraph-image\"><img src=\"/images/bleeding.png\" alt=\"임플란트 모형과 확대경, 출혈을 상징하는 아이콘\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section class=\"section\" id=\"lifespan\"><h2><span>02</span>피가 나는 이유: 임플란트 주변의 염증</h2><p>임플란트 주변에도 세균성 치태가 쌓일 수 있습니다. 치태가 주변 잇몸을 자극하면 붉어짐, 부기, 양치할 때의 출혈 같은 변화가 나타날 수 있습니다.\n\n반복되는 출혈을 단순히 양치 때문이라고 넘기기보다 치과에서 원인을 확인하세요. 과거 치주질환, 치태 관리 상태, 흡연 등은 임플란트 주변 조직의 건강을 살필 때 함께 고려하는 요소입니다.</p><figure class=\"paragraph-image\"><img src=\"/images/bleeding.png\" alt=\"임플란트 주변 잇몸을 확대경으로 살펴보는 설명 모형\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section class=\"section\" id=\"parts\"><h2><span>03</span>점막염과 주위염, 무엇이 다른가요?</h2><p>임플란트 주위 점막염은 주변의 연조직에 염증이 있으면서 지지하는 뼈의 소실은 없는 상태를 말합니다. 일찍 발견하면 위생 관리와 전문적인 치료로 호전될 가능성이 있습니다.\n\n임플란트 주위염은 주변 조직의 염증과 함께 임플란트를 지지하는 뼈에 손상이 있는 상태입니다. 출혈이 얼마나 많이 보이는지만으로 두 상태를 구분할 수 없으므로 치과 평가가 필요합니다.</p><figure class=\"paragraph-image\"><img src=\"/images/lifespan.png\" alt=\"주변 조직의 상태를 함께 살펴보는 임플란트 모형과 확대경\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section class=\"section\" id=\"care\"><h2><span>04</span>관리 방법: 치과 안내에 맞춘 위생 관리</h2><p>임플란트와 주변 치아를 꾸준히 청결하게 관리하는 것은 중요합니다. 담당 치과에서 안내한 방법으로 양치하고 치아 사이를 관리하세요. 반복되는 출혈이 있다면 도구와 사용 방법이 적절한지도 상담할 수 있습니다.\n\n집에서의 관리만으로 모든 염증을 해결할 수 있는 것은 아닙니다. 치과에서 전문적인 세정이나 추가 치료가 필요할 수 있고, 치료 후에도 상태를 다시 확인하는 일정이 중요합니다.</p><figure class=\"paragraph-image\"><img src=\"/images/care.png\" alt=\"칫솔과 치간 관리 도구를 임플란트 모형 옆에 놓은 그림\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section class=\"section\" id=\"signs\"><h2><span>05</span>이런 변화가 있다면 치과에 연락하세요</h2><p>양치나 치아 사이 관리 중 출혈이 반복되거나 잇몸이 붓고, 입 냄새나 불쾌한 맛이 새로 나타나면 치과에 문의하세요. 임플란트가 흔들리거나 통증이 있으면 바로 담당 치과에 알려야 합니다.\n\n다음 정기검진까지 기다리기보다 증상이 언제부터 시작됐는지, 어느 부위에서 생기는지 정리해서 전달하세요. 이런 변화만으로 치료 방법이 정해지는 것은 아니며, 치과에서 원인과 상태를 확인해야 합니다.</p><figure class=\"paragraph-image\"><img src=\"/images/signs.png\" alt=\"잇몸 주변의 불편함을 치과 의료진과 상담하는 인물 그림\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section class=\"section\" id=\"checkup\"><h2><span>06</span>자주 묻는 질문</h2><p>Q. 한 번 피가 났는데도 반드시 임플란트를 교체하나요?\nA. 출혈 하나만으로 교체를 결정할 수는 없습니다. 반복 여부와 주변 조직의 상태를 확인해야 합니다.\n\nQ. 양치만 잘하면 주위염도 해결되나요?\nA. 위생 관리는 중요하지만, 뼈까지 영향을 받은 상태라면 추가 치료가 필요할 수 있습니다. 상태에 맞는 치료 계획을 상담하세요.\n\nQ. 임플란트가 흔들리면 어떻게 하나요?\nA. 바로 담당 치과에 알리세요. 연결 부품의 느슨함과 몸체의 안정성 문제 등은 구분해서 평가해야 합니다.</p><figure class=\"paragraph-image\"><img src=\"/images/checkup.png\" alt=\"치과에서 점검 결과와 치료 계획을 상담하는 그림\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section class=\"section\" id=\"summary\"><h2><span>07</span>출혈을 무시하지 말고, 상태부터 확인하세요</h2><p>임플란트 잇몸 출혈은 곧바로 교체가 필요하다는 뜻은 아니지만 주변 조직을 살펴봐야 하는 신호일 수 있습니다. 반복되는 출혈이나 흔들림, 통증이 있다면 치과에 문의하세요.\n\n임플란트를 유지할 수 있는지, 어떤 치료가 필요한지는 개별 상태에 따라 다릅니다. 이 글은 일반적인 정보이며 개인의 진단과 치료 계획을 대신하지 않습니다.</p><figure class=\"paragraph-image\"><img src=\"/images/summary.png\" alt=\"위생 관리와 정기 점검을 함께 표현한 임플란트 모형\" loading=\"lazy\" width=\"1536\" height=\"1024\"></figure></section><section id=\"contact\"><h2>홈페이지 · 상담 · 예약</h2><div class=\"contact-grid\"><a class=\"contact-link\" href=\"https://wonderplant1.kr/\"><b>W</b><div><small>CONTACT</small>홈페이지 방문 · 원더플치과의원</div></a><a class=\"contact-link\" href=\"tel:029862275\"><b>☎</b><div><small>CONTACT</small>전화 예약 · 원더플치과의원</div></a><a class=\"contact-link\" href=\"https://booking.naver.com/booking/13/bizes/270552\"><b>N</b><div><small>CONTACT</small>온라인 예약 · 원더플치과의원</div></a><a class=\"contact-link\" href=\"https://pf.kakao.com/_ZxmjxcT\"><b>T</b><div><small>CONTACT</small>상담 채널 · 원더플치과의원</div></a></div><p class=\"caption\">치과 연결 정보가 등록되면 버튼이 활성화됩니다.</p></section><section class=\"related-post\"><h2>함께 읽는 글</h2><a href=\"/implant-lifespan.html\">임플란트 교체 시기와 수명, 언제 다시 치료해야 할까요? →</a></section><div class=\"tags\" aria-label=\"관련 키워드\"><span class=\"tag\">#임플란트 잇몸 출혈</span><span class=\"tag\">#임플란트 주위염</span><span class=\"tag\">#임플란트 주위 점막염</span><span class=\"tag\">#임플란트 관리</span><span class=\"tag\">#임플란트 교체</span></div><div class=\"notice\">이 글은 일반적인 건강 정보를 정리한 정보입니다. 개인의 진단·치료를 대신하지 않습니다. 치료 방법과 결과는 개인 상태에 따라 다릅니다.</div></article>","original_schema":{"@context":"https://schema.org","@type":"BlogPosting","headline":"임플란트 잇몸 출혈, 피가 나면 교체해야 하나요?","description":"임플란트 주변 잇몸에서 피가 난다고 해서 곧바로 임플란트를 교체하는 것은 아닙니다. 출혈은 주변 잇몸의 염증을 알리는 신호일 수 있으며, 교체 여부는 뼈와 임플란트의 안정성 등 실제 상태를 확인한 뒤 판단합니다.","datePublished":"2026-10-08","dateCreated":"2026-10-08","dateModified":"2026-10-08","author":{"@type":"Organization","name":"원더플치과의원 블로그"},"keywords":["임플란트 잇몸 출혈","임플란트 주위염","임플란트 주위 점막염","임플란트 관리","임플란트 교체"],"url":"https://beautiful-semolina-aa2c94.netlify.app/implant-gum-bleeding.html","mainEntityOfPage":"https://beautiful-semolina-aa2c94.netlify.app/implant-gum-bleeding.html","articleBody":"출혈이 곧 임플란트 교체를 뜻하지는 않습니다\n양치할 때 임플란트 주변에서 피가 나면 임플란트가 망가진 것은 아닌지 걱정될 수 있습니다. 하지만 출혈만으로 임플란트 몸체를 제거하거나 다시 심어야 한다고 판단할 수는 없습니다.\n\n치과에서는 주변 조직에 어떤 문제가 있는지 확인합니다. 잇몸에 국한된 염증과 지지하는 뼈까지 영향을 받은 상태는 구분해야 하며, 임플란트가 흔들리는지도 평가합니다.\n\n피가 나는 이유: 임플란트 주변의 염증\n임플란트 주변에도 세균성 치태가 쌓일 수 있습니다. 치태가 주변 잇몸을 자극하면 붉어짐, 부기, 양치할 때의 출혈 같은 변화가 나타날 수 있습니다.\n\n반복되는 출혈을 단순히 양치 때문이라고 넘기기보다 치과에서 원인을 확인하세요. 과거 치주질환, 치태 관리 상태, 흡연 등은 임플란트 주변 조직의 건강을 살필 때 함께 고려하는 요소입니다.\n\n점막염과 주위염, 무엇이 다른가요?\n임플란트 주위 점막염은 주변의 연조직에 염증이 있으면서 지지하는 뼈의 소실은 없는 상태를 말합니다. 일찍 발견하면 위생 관리와 전문적인 치료로 호전될 가능성이 있습니다.\n\n임플란트 주위염은 주변 조직의 염증과 함께 임플란트를 지지하는 뼈에 손상이 있는 상태입니다. 출혈이 얼마나 많이 보이는지만으로 두 상태를 구분할 수 없으므로 치과 평가가 필요합니다.\n\n관리 방법: 치과 안내에 맞춘 위생 관리\n임플란트와 주변 치아를 꾸준히 청결하게 관리하는 것은 중요합니다. 담당 치과에서 안내한 방법으로 양치하고 치아 사이를 관리하세요. 반복되는 출혈이 있다면 도구와 사용 방법이 적절한지도 상담할 수 있습니다.\n\n집에서의 관리만으로 모든 염증을 해결할 수 있는 것은 아닙니다. 치과에서 전문적인 세정이나 추가 치료가 필요할 수 있고, 치료 후에도 상태를 다시 확인하는 일정이 중요합니다.\n\n이런 변화가 있다면 치과에 연락하세요\n양치나 치아 사이 관리 중 출혈이 반복되거나 잇몸이 붓고, 입 냄새나 불쾌한 맛이 새로 나타나면 치과에 문의하세요. 임플란트가 흔들리거나 통증이 있으면 바로 담당 치과에 알려야 합니다.\n\n다음 정기검진까지 기다리기보다 증상이 언제부터 시작됐는지, 어느 부위에서 생기는지 정리해서 전달하세요. 이런 변화만으로 치료 방법이 정해지는 것은 아니며, 치과에서 원인과 상태를 확인해야 합니다.\n\n자주 묻는 질문\nQ. 한 번 피가 났는데도 반드시 임플란트를 교체하나요?\nA. 출혈 하나만으로 교체를 결정할 수는 없습니다. 반복 여부와 주변 조직의 상태를 확인해야 합니다.\n\nQ. 양치만 잘하면 주위염도 해결되나요?\nA. 위생 관리는 중요하지만, 뼈까지 영향을 받은 상태라면 추가 치료가 필요할 수 있습니다. 상태에 맞는 치료 계획을 상담하세요.\n\nQ. 임플란트가 흔들리면 어떻게 하나요?\nA. 바로 담당 치과에 알리세요. 연결 부품의 느슨함과 몸체의 안정성 문제 등은 구분해서 평가해야 합니다.\n\n출혈을 무시하지 말고, 상태부터 확인하세요\n임플란트 잇몸 출혈은 곧바로 교체가 필요하다는 뜻은 아니지만 주변 조직을 살펴봐야 하는 신호일 수 있습니다. 반복되는 출혈이나 흔들림, 통증이 있다면 치과에 문의하세요.\n\n임플란트를 유지할 수 있는지, 어떤 치료가 필요한지는 개별 상태에 따라 다릅니다. 이 글은 일반적인 정보이며 개인의 진단과 치료 계획을 대신하지 않습니다.","citation":["https://www.perio.org/for-patients/periodontal-treatments-and-procedures/dental-implant-procedures/peri-implant-diseases/","https://www.efp.org/for-patients/dental-implants/peri-implant-diseases/","https://www.efp.org/for-patients/dental-implants/peri-implant-disease-treatment/","https://www.fda.gov/medical-devices/dental-devices/dental-implants-what-you-should-know"]},"published_at":"2026-10-08","created_at":"2026-10-08"}]'::jsonb) as p(legacy_id text,title text,slug text,summary text,content jsonb,legacy_article_html text,original_schema jsonb,thumbnail text,thumbnail_alt text,category_id text,created_at timestamptz,published_at timestamptz)
